  it('keeps the usage an earlier round reported when a later round reports none', async () => {
    const usage: UsageMetadata = {inputTokens: 11, outputTokens: 3, totalTokens: 14};
    let seen: UsageMetadata | undefined;
    const hooks: OrchestratorHooks = {
      afterModelResponse: async (_session, _text, reported) => {
        seen = reported;
      },
    };
    const orchestrator = createChatOrchestrator(
      scriptedProvider([
        [TOOL_CALL, {type: 'stop', stopReason: 'tool_use', usage}],
        [{type: 'text', text: 'done'}, STOP_DONE],
      ]),
      promptBuilder,
      registryReturning({result: 'r'}),
      {hooks}
    );

    await orchestrator.processMessage(createSession('ask'));

    expect(seen).toEqual(usage);
  });

  it('continues the tool loop when execute returns a validation rejection result without calling the executor', async () => {
    const registry = new ToolRegistry();
    let executorCalled = false;
    registry.register({name: 'fail', description: 'desc', inputSchema: {type: 'object', required: ['x']}}, async () => {
      executorCalled = true;
      return 'ok';
    });

    const provider = scriptedProvider([
      [{type: 'tool_use', toolCall: {id: 'c1', name: 'fail', input: {}}}, STOP_FOR_TOOL],
      [{type: 'text', text: 'done'}, STOP_DONE],
    ]);
    const orchestrator = createChatOrchestrator(provider, promptBuilder, registry);

    const chunks = await chunksFrom(orchestrator.processMessageStream(createSession('ask')));

    expect({
      chunkTypes: chunks.map(c => c.type),
      executorCalled,
    }).toEqual({
      chunkTypes: ['tool_use', 'stop', 'text', 'stop'],
      executorCalled: false,
    });
  });

  it('passes the validation rejection result back to the provider on the next round', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {name: 'fail', description: 'desc', inputSchema: {type: 'object', required: ['x']}},
      async () => 'ok'
    );

    const allCaptured: Message[][] = [];
    const provider: AIProvider = {
      async *sendMessage(params: SendMessageParams): AsyncGenerator<MessageChunk> {
        allCaptured.push([...params.messages]);
        if (allCaptured.length !== 1) {
          yield {type: 'text', text: 'done'};
          yield {type: 'stop', stopReason: 'end_turn'};
          return;
        }

        yield {type: 'tool_use', toolCall: {id: 'c1', name: 'fail', input: {}}};
        yield {type: 'stop', stopReason: 'tool_use'};
      },
      async generateStructured<T>(): Promise<T> {
        return {} as T;
      },
    };

    const orchestrator = createChatOrchestrator(provider, promptBuilder, registry);
    await orchestrator.processMessage(createSession('ask'));

    const capturedMessages = allCaptured[allCaptured.length - 1];
    const toolResult = capturedMessages[2] as ToolResultMessage;
    const content = toolResult.content[0];
    expect({
      count: capturedMessages.length,
      role: toolResult.role,
      contentType: content.type,
      contentBody: content.content,
    }).toEqual({
      count: 3, // [user, assistant-tool-use, user-tool-result]
      role: 'user',
      contentType: 'tool_result',
      contentBody: expect.stringMatching(/Validation failed.*missing required property: x/),
    });
  });
});

